const C=root.DCCore,$=id=>document.getElementById(id),median=values=>{const a=values.slice().sort((x,y)=>x-y),i=a.length>>1;return a.length%2?a[i]:(a[i-1]+a[i])/2;};
function deliveryLag(stamp,now,origin=0){let time=Number(stamp);if(time>1e12)time-=origin;const lag=now-time;return Number.isFinite(lag)&&lag>=0&&lag<=2000?lag:null;}
