  const css=getComputedStyle(view),accent=css.getPropertyValue('--accent').trim()||'#c0a0ff',cy=previewHeight/2,end=previewWidth*.8,start=previewWidth*.12;c.strokeStyle=accent;c.lineWidth=2;c.globalAlpha=.35;c.beginPath();c.moveTo(start,cy);c.lineTo(end,cy);c.stroke();c.globalAlpha=1;c.beginPath();c.moveTo(end,cy-46);c.lineTo(end,cy+46);c.stroke();
