  if(!running||!trial)return;const accepted=context.currentTime,lag=deliveryLag(event.timeStamp,performance.now(),performance.timeOrigin),sample=trial.tap(accepted,lag);if(!sample){status('本拍已采集或输入超出 ±240ms 采集窗，请跟随下一拍或重测。');return;}
